        s=cand[vals.index(min(vals.values()))]
    nl=set()
    for i in range(H):
        for j in range(s):
            v=I[i][j]
            if v!=bg and v==v: pass  # placeholder - fix below
    nl={I[i][j] for i in range(H) for j in range(s) if I[i][j]!=bg}
    nr={I[i][j] for i in range(H) for j in range(s+1,W) if I[i][j]!=bg}
